from collections import Counter
comp_sink = Counter()

visited = set()
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if grid_np[r, c] == 7 and (r, c) not in visited:
            comp_id = len(comp_sink)
            queue = [(r, c)]
            visited.add((r, c))
            while queue:
                cr, cc = queue.pop(0)
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < len(test_input) and 0 <= nc < len(test_input[0]):
                        if grid_np[nr, nc] == 7 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
            size = len(visited)
            comp_sink[size] += 1

print("Component sizes:")
for size in sorted(comp_sink.keys()):
    print(f"  Size {size}: {comp_sink[size]} components")

# Create output grid
output_grid = grid_np.copy()
visited = set()

grid_ids = {}
for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if grid_np[r, c] == 7 and (r, c) not in visited:
            comp_id = len(grid_ids)
            queue = [(r, c)]
            visited.add((r, c))
            while queue:
                cr, cc = queue.pop(0)
                grid_ids[(cr, cc)] = comp_id
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < len(test_input) and 0 <= nc < len(test_input[0]):
                        if grid_np[nr, nc] == 7 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            grid_ids[(nr, nc)] = comp_id
                            queue.append((nr, nc))

# Map sizes
