for r in range(len(test_input)):
    for c in range(len(test_input[0])):
        if grid_np[r, c] == 7:
            comp_id = grid_ids[(r, c)]
            # Recalculate size - inefficient but correct
            size = len([k for k, v in grid_ids.items() if v == comp_id])
            if size == 2:
